-- ─────────────────────────────────────────────────────────────────────────────
-- Seed: Study Diagram Library (spec-first)
--
-- Each row carries a structured diagram_spec (JSON ground truth of labels,
-- roles, relationships and per-level depth notes). The PNG itself is rendered
-- lazily by the generate-library-diagram edge function on first open and
-- cached in the public 'library-diagrams' bucket; image_url is then filled in.
--
-- curriculum is NULL on purpose: these are cross-curriculum canonical topics,
-- and the personalization matcher shows untagged resources to every
-- curriculum while still filtering by subject and grade band. depth_notes in
-- the spec drive level-appropriate AI explanations instead.
--
-- Idempotent: NOT EXISTS on (title, kind).
-- ─────────────────────────────────────────────────────────────────────────────

INSERT INTO public.library_system_resources
  (title, kind, subject, topic, curriculum, grade_levels, thumbnail_url, description, diagram_spec)
SELECT v.title, v.kind, v.subject, v.topic, v.curriculum, v.grade_levels, v.thumbnail_url, v.description, v.diagram_spec
FROM (VALUES
('Human Heart: Structure and Blood Flow','diagram','Biology','The heart & circulation',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','Cross-section of the human heart showing all four chambers, valves and major vessels, with arrows for oxygenated (red) and deoxygenated (blue) blood.','{"version": 1, "title": "Human Heart: Structure and Blood Flow", "caption": "Cross-section of the human heart showing all four chambers, valves and major vessels, with arrows for oxygenated (red) and deoxygenated (blue) blood.", "subject": "Biology", "topic": "The heart & circulation", "elements": [{"label": "Right atrium", "role": "receives deoxygenated blood from the body via the vena cavae"}, {"label": "Right ventricle", "role": "pumps deoxygenated blood to the lungs via the pulmonary artery"}, {"label": "Left atrium", "role": "receives oxygenated blood from the lungs via the pulmonary veins"}, {"label": "Left ventricle", "role": "pumps oxygenated blood to the body via the aorta; thickest wall"}, {"label": "Tricuspid valve", "role": "prevents backflow from right ventricle to right atrium"}, {"label": "Bicuspid (mitral) valve", "role": "prevents backflow from left ventricle to left atrium"}, {"label": "Semilunar valves", "role": "prevent backflow from arteries into the ventricles"}, {"label": "Aorta", "role": "main artery carrying oxygenated blood to the body"}, {"label": "Pulmonary artery", "role": "only artery carrying deoxygenated blood"}, {"label": "Pulmonary veins", "role": "only veins carrying oxygenated blood"}], "relationships": ["Double circulation: pulmonary circuit (heart→lungs→heart) and systemic circuit (heart→body→heart)", "Left ventricle wall is thicker than right because it pumps blood at higher pressure around the whole body", "Valves open and close due to pressure differences, keeping flow one-way"], "depth_notes": {"JC": "Identify the four chambers and the direction of blood flow.", "O-Level": "Label chambers, valves and vessels; explain double circulation and why the left ventricle wall is thicker.", "A-Level": "Explain the cardiac cycle with pressure changes, myogenic stimulation (SAN, AVN, Purkyne fibres) and interpret pressure–volume graphs."}, "style": "studysync-edu-v1"}'::jsonb),
('Photosynthesis in a Green Leaf','diagram','Biology','Photosynthesis',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','Leaf cross-section with tissues labelled, plus inputs/outputs and both the word and balanced chemical equations for photosynthesis.','{"version": 1, "title": "Photosynthesis in a Green Leaf", "caption": "Leaf cross-section with tissues labelled, plus inputs/outputs and both the word and balanced chemical equations for photosynthesis.", "subject": "Biology", "topic": "Photosynthesis", "elements": [{"label": "Waxy cuticle", "role": "transparent, reduces water loss"}, {"label": "Upper epidermis", "role": "transparent layer letting light through"}, {"label": "Palisade mesophyll", "role": "tightly packed cells with most chloroplasts; main photosynthesis site"}, {"label": "Spongy mesophyll", "role": "air spaces for gas diffusion"}, {"label": "Stoma (pore)", "role": "entry of CO2, exit of O2 and water vapour"}, {"label": "Guard cells", "role": "open and close the stoma"}, {"label": "Xylem", "role": "brings water and minerals to the leaf"}, {"label": "Phloem", "role": "carries away sugars (translocation)"}, {"label": "Word equation", "role": "carbon dioxide + water --(light, chlorophyll)--> glucose + oxygen"}, {"label": "Balanced equation", "role": "6CO2 + 6H2O --(light energy)--> C6H12O6 + 6O2"}], "relationships": ["Light intensity, CO2 concentration and temperature are limiting factors", "Leaf adaptations (thin, broad, air spaces, many chloroplasts near surface) maximise the rate"], "depth_notes": {"JC": "State the word equation and what plants need to make food.", "O-Level": "Label the leaf tissues, give both equations, and explain leaf adaptations and limiting factors.", "A-Level": "Distinguish light-dependent reactions (thylakoids: photolysis, ATP, NADPH) from the Calvin cycle (stroma: CO2 fixation by RuBisCO)."}, "style": "studysync-edu-v1"}'::jsonb),
('Plant Cell vs Animal Cell','diagram','Biology','Cells',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','Side-by-side labelled comparison of a typical plant cell and animal cell, highlighting structures unique to plants.','{"version": 1, "title": "Plant Cell vs Animal Cell", "caption": "Side-by-side labelled comparison of a typical plant cell and animal cell, highlighting structures unique to plants.", "subject": "Biology", "topic": "Cells", "elements": [{"label": "Cell membrane", "role": "controls entry and exit of substances (both cells)"}, {"label": "Cytoplasm", "role": "site of chemical reactions (both cells)"}, {"label": "Nucleus", "role": "contains DNA; controls the cell (both cells)"}, {"label": "Mitochondria", "role": "site of aerobic respiration (both cells)"}, {"label": "Ribosomes", "role": "site of protein synthesis (both cells)"}, {"label": "Cell wall (plant only)", "role": "cellulose; gives rigid support"}, {"label": "Chloroplasts (plant only)", "role": "contain chlorophyll; photosynthesis"}, {"label": "Large permanent vacuole (plant only)", "role": "cell sap; maintains turgor"}], "relationships": ["Plant cells have all animal-cell structures PLUS cell wall, chloroplasts and a permanent vacuole", "Not every plant cell has chloroplasts (e.g. root cells)"], "depth_notes": {"JC": "Name the parts common to both cells and the three plant-only structures.", "O-Level": "State the function of every organelle and compare the two cell types in a table.", "A-Level": "Extend to ultrastructure: ER, Golgi, lysosomes, 80S vs 70S ribosomes, and the endosymbiont theory for mitochondria/chloroplasts."}, "style": "studysync-edu-v1"}'::jsonb),
('The Human Digestive System','diagram','Biology','Digestion',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','Outline of the human alimentary canal and associated organs, in order, with the role of each in digestion and absorption.','{"version": 1, "title": "The Human Digestive System", "caption": "Outline of the human alimentary canal and associated organs, in order, with the role of each in digestion and absorption.", "subject": "Biology", "topic": "Digestion", "elements": [{"label": "Mouth", "role": "mechanical digestion; salivary amylase starts starch digestion"}, {"label": "Oesophagus", "role": "peristalsis moves the bolus to the stomach"}, {"label": "Stomach", "role": "churns food; pepsin (protease) digests protein; HCl kills microbes"}, {"label": "Liver", "role": "produces bile which emulsifies fats and neutralises stomach acid"}, {"label": "Gall bladder", "role": "stores bile"}, {"label": "Pancreas", "role": "secretes amylase, protease (trypsin) and lipase into the duodenum"}, {"label": "Small intestine (duodenum + ileum)", "role": "completes digestion; villi absorb nutrients"}, {"label": "Large intestine (colon)", "role": "absorbs water"}, {"label": "Rectum and anus", "role": "stores and egests faeces"}], "relationships": ["Enzymes: carbohydrase→simple sugars, protease→amino acids, lipase→fatty acids + glycerol", "Villi adaptations: large surface area, one-cell-thick wall, capillaries and lacteal"], "depth_notes": {"JC": "Put the organs in order and describe what happens to food in each.", "O-Level": "Name the enzymes, their substrates, products and optimum conditions; explain villus adaptations.", "A-Level": "Explain enzyme specificity and the role of membrane-bound disaccharidases; link absorption to co-transport of glucose with sodium ions."}, "style": "studysync-edu-v1"}'::jsonb),
('Insect-Pollinated Flower (Cross-Section)','diagram','Biology','Reproduction in plants',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','Cross-section of an insect-pollinated flower with male and female parts labelled and an inset showing pollen transfer by an insect.','{"version": 1, "title": "Insect-Pollinated Flower (Cross-Section)", "caption": "Cross-section of an insect-pollinated flower with male and female parts labelled and an inset showing pollen transfer by an insect.", "subject": "Biology", "topic": "Reproduction in plants", "elements": [{"label": "Petal", "role": "large and brightly coloured to attract insects"}, {"label": "Sepal", "role": "protects the flower in bud"}, {"label": "Anther", "role": "produces pollen (male gamete)"}, {"label": "Filament", "role": "holds up the anther"}, {"label": "Stamen", "role": "male part = anther + filament"}, {"label": "Stigma", "role": "sticky surface where pollen lands"}, {"label": "Style", "role": "connects stigma to ovary"}, {"label": "Ovary", "role": "contains ovules"}, {"label": "Ovule", "role": "contains the female gamete; becomes the seed"}, {"label": "Nectary", "role": "produces nectar to reward insects"}], "relationships": ["Pollination = transfer of pollen from anther to stigma; fertilisation = fusion of male nucleus with egg cell in the ovule", "Insect-pollinated flowers differ from wind-pollinated: petals, nectar, sticky spiky pollen vs small dull flowers with dangling anthers and smooth light pollen"], "depth_notes": {"JC": "Label the flower parts and state which are male and female.", "O-Level": "Compare insect- vs wind-pollinated flowers and describe the steps from pollination to seed formation.", "A-Level": "Detail double events after pollination: pollen tube growth, fertilisation, and development of ovule→seed, ovary→fruit."}, "style": "studysync-edu-v1"}'::jsonb),
('The Carbon Cycle','diagram','Biology','Ecology & cycles',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','Flow diagram of carbon movement between the atmosphere, plants, animals, decomposers and fossil fuels.','{"version": 1, "title": "The Carbon Cycle", "caption": "Flow diagram of carbon movement between the atmosphere, plants, animals, decomposers and fossil fuels.", "subject": "Biology", "topic": "Ecology & cycles", "elements": [{"label": "CO2 in the atmosphere", "role": "central reservoir (~0.04% of air)"}, {"label": "Photosynthesis", "role": "removes CO2 from air into plant carbohydrates"}, {"label": "Respiration (plants, animals, decomposers)", "role": "returns CO2 to the air"}, {"label": "Feeding", "role": "transfers carbon compounds from plants to animals"}, {"label": "Death and decay", "role": "decomposers break down dead matter"}, {"label": "Fossilisation", "role": "dead matter under pressure becomes coal, oil, gas"}, {"label": "Combustion", "role": "burning fossil fuels and wood releases CO2"}], "relationships": ["Photosynthesis is the ONLY arrow removing CO2 from the atmosphere in the basic cycle", "Deforestation and increased combustion raise atmospheric CO2 — link to the enhanced greenhouse effect"], "depth_notes": {"JC": "Trace carbon around the cycle naming each process.", "O-Level": "Explain each arrow and how human activity unbalances the cycle.", "A-Level": "Add oceanic uptake, carbonates and a quantitative treatment of sources/sinks; evaluate climate implications."}, "style": "studysync-edu-v1"}'::jsonb),
('DNA Structure and Base Pairing','diagram','Biology','Inheritance',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','The DNA double helix untwisted to show the sugar-phosphate backbone and complementary base pairs with hydrogen bonds.','{"version": 1, "title": "DNA Structure and Base Pairing", "caption": "The DNA double helix untwisted to show the sugar-phosphate backbone and complementary base pairs with hydrogen bonds.", "subject": "Biology", "topic": "Inheritance", "elements": [{"label": "Sugar-phosphate backbone", "role": "alternating deoxyribose and phosphate groups"}, {"label": "Nucleotide", "role": "one sugar + one phosphate + one base"}, {"label": "Adenine (A)", "role": "always pairs with Thymine (T) — 2 hydrogen bonds"}, {"label": "Thymine (T)", "role": "pairs with Adenine"}, {"label": "Guanine (G)", "role": "always pairs with Cytosine (C) — 3 hydrogen bonds"}, {"label": "Cytosine (C)", "role": "pairs with Guanine"}, {"label": "Hydrogen bonds", "role": "hold the two strands together"}, {"label": "Double helix", "role": "two antiparallel strands twisted together"}], "relationships": ["Complementary base pairing (A–T, G–C) means each strand can act as a template for copying", "The sequence of bases codes for the sequence of amino acids in proteins"], "depth_notes": {"O-Level": "Describe the double helix, name the four bases and the pairing rule.", "A-Level": "Explain antiparallel strands, phosphodiester bonds, semi-conservative replication and the roles of DNA polymerase and helicase."}, "style": "studysync-edu-v1"}'::jsonb),
('Structure of the Human Eye','diagram','Biology','The eye',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','Horizontal cross-section of the eye with the path of light shown from cornea to retina.','{"version": 1, "title": "Structure of the Human Eye", "caption": "Horizontal cross-section of the eye with the path of light shown from cornea to retina.", "subject": "Biology", "topic": "The eye", "elements": [{"label": "Cornea", "role": "transparent front layer; does most refraction of light"}, {"label": "Iris", "role": "coloured muscle controlling pupil size"}, {"label": "Pupil", "role": "hole letting light in"}, {"label": "Lens", "role": "fine-focuses light; shape changed by ciliary muscles"}, {"label": "Ciliary muscles", "role": "contract/relax to change lens shape (accommodation)"}, {"label": "Suspensory ligaments", "role": "attach lens to ciliary muscles"}, {"label": "Retina", "role": "light-sensitive layer (rods and cones)"}, {"label": "Fovea", "role": "region of sharpest colour vision (cones only)"}, {"label": "Optic nerve", "role": "carries impulses to the brain"}, {"label": "Blind spot", "role": "where the optic nerve leaves; no receptors"}], "relationships": ["Accommodation: near object → ciliary muscles contract, ligaments slack, lens fat; distant object → the reverse", "Pupil reflex: bright light → circular muscles of iris contract → pupil constricts"], "depth_notes": {"JC": "Label the parts of the eye and the path of light.", "O-Level": "Explain accommodation and the pupil reflex as examples of reflex control.", "A-Level": "Detail rods vs cones (sensitivity, acuity, distribution) and the visual pathway."}, "style": "studysync-edu-v1"}'::jsonb),
('The Lungs and Gas Exchange','diagram','Biology','Gas exchange',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/17a184/ffffff?text=Biology%0ADiagram','The human thorax showing the airway tree down to an enlarged alveolus with a capillary, and the direction of oxygen and carbon dioxide diffusion.','{"version": 1, "title": "The Lungs and Gas Exchange", "caption": "The human thorax showing the airway tree down to an enlarged alveolus with a capillary, and the direction of oxygen and carbon dioxide diffusion.", "subject": "Biology", "topic": "Gas exchange", "elements": [{"label": "Trachea", "role": "windpipe held open by C-shaped cartilage rings"}, {"label": "Bronchi", "role": "two tubes, one to each lung"}, {"label": "Bronchioles", "role": "fine branching tubes"}, {"label": "Alveoli", "role": "millions of air sacs; the gas-exchange surface"}, {"label": "Capillary network", "role": "surrounds each alveolus"}, {"label": "Diaphragm", "role": "muscle sheet; contracts and flattens during inhalation"}, {"label": "Ribs and intercostal muscles", "role": "move ribcage up/out to inhale"}, {"label": "O2 arrow", "role": "diffuses alveolus → blood"}, {"label": "CO2 arrow", "role": "diffuses blood → alveolus"}], "relationships": ["Alveoli adaptations: huge surface area, one-cell-thick walls, moist lining, rich blood supply maintaining steep concentration gradients", "Ventilation vs gas exchange vs respiration are three different things — a classic exam trap"], "depth_notes": {"JC": "Label the airway and describe breathing in and out.", "O-Level": "Explain alveolar adaptations and pressure/volume changes during ventilation.", "A-Level": "Link to Fick''s law, partial pressures and the oxygen dissociation curve."}, "style": "studysync-edu-v1"}'::jsonb),
('Electrolysis of Acidified Water','diagram','Chemistry','Electrolysis',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/3860f0/ffffff?text=Chemistry%0ADiagram','Hofmann-style setup decomposing water into hydrogen and oxygen, with electrodes, half-equations and the 2:1 gas ratio shown.','{"version": 1, "title": "Electrolysis of Acidified Water", "caption": "Hofmann-style setup decomposing water into hydrogen and oxygen, with electrodes, half-equations and the 2:1 gas ratio shown.", "subject": "Chemistry", "topic": "Electrolysis", "elements": [{"label": "Cathode (−)", "role": "hydrogen gas forms here"}, {"label": "Anode (+)", "role": "oxygen gas forms here"}, {"label": "Electrolyte", "role": "water acidified with dilute sulfuric acid (provides ions)"}, {"label": "Cathode half-equation", "role": "2H+(aq) + 2e− → H2(g)"}, {"label": "Anode half-equation", "role": "2H2O(l) → O2(g) + 4H+(aq) + 4e−"}, {"label": "Gas ratio", "role": "volume of hydrogen : oxygen = 2 : 1"}, {"label": "DC power supply", "role": "drives the non-spontaneous reaction"}, {"label": "Test for H2", "role": "lit splint gives a squeaky pop"}, {"label": "Test for O2", "role": "relights a glowing splint"}], "relationships": ["Reduction happens at the cathode (gain of electrons), oxidation at the anode (loss) — OILRIG", "Pure water barely conducts; the acid supplies mobile ions"], "depth_notes": {"O-Level": "Label electrodes and products, give the gas tests and the 2:1 ratio.", "A-Level": "Write and combine half-equations, calculate quantities using Faraday''s constant (Q = It, moles of e−)."}, "style": "studysync-edu-v1"}'::jsonb),
('Periodic Table: Trends and Groups','diagram','Chemistry','Periodic table',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/3860f0/ffffff?text=Chemistry%0ADiagram','Periodic table coloured by metals/metalloids/non-metals with arrows showing trends in atomic radius, reactivity, electronegativity and ionisation energy.','{"version": 1, "title": "Periodic Table: Trends and Groups", "caption": "Periodic table coloured by metals/metalloids/non-metals with arrows showing trends in atomic radius, reactivity, electronegativity and ionisation energy.", "subject": "Chemistry", "topic": "Periodic table", "elements": [{"label": "Groups (vertical)", "role": "same number of outer electrons → similar chemistry"}, {"label": "Periods (horizontal)", "role": "number of electron shells increases down the table"}, {"label": "Group 1 alkali metals", "role": "reactivity INCREASES down the group"}, {"label": "Group 17 halogens", "role": "reactivity DECREASES down the group"}, {"label": "Group 18 noble gases", "role": "full outer shells; unreactive"}, {"label": "Atomic radius", "role": "increases down a group, decreases across a period"}, {"label": "Electronegativity", "role": "increases across a period, decreases down a group"}, {"label": "Ionisation energy", "role": "increases across a period, decreases down a group"}, {"label": "Metals / metalloids / non-metals", "role": "staircase divide on the right side"}], "relationships": ["Down a group: more shells → outer electron further and more shielded → easier to lose (metals more reactive)", "Across a period: more protons, same shells → stronger pull → smaller atoms"], "depth_notes": {"O-Level": "Explain group/period structure and the reactivity trends of Groups 1 and 17.", "A-Level": "Explain all four trends using nuclear charge, shielding and distance; account for anomalies (e.g. ionisation-energy dips at Groups 13 and 16)."}, "style": "studysync-edu-v1"}'::jsonb),
('Atomic Structure: The First 20 Elements','diagram','Chemistry','Atomic structure',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/3860f0/ffffff?text=Chemistry%0ADiagram','Bohr model of an atom with labelled subatomic particles and electron shell rules, using sodium (2,8,1) as the worked example.','{"version": 1, "title": "Atomic Structure: The First 20 Elements", "caption": "Bohr model of an atom with labelled subatomic particles and electron shell rules, using sodium (2,8,1) as the worked example.", "subject": "Chemistry", "topic": "Atomic structure", "elements": [{"label": "Proton", "role": "charge +1, relative mass 1, in the nucleus"}, {"label": "Neutron", "role": "charge 0, relative mass 1, in the nucleus"}, {"label": "Electron", "role": "charge −1, mass ~1/1840, orbits in shells"}, {"label": "Nucleus", "role": "protons + neutrons; nearly all the mass"}, {"label": "Electron shells", "role": "hold up to 2, 8, 8 (first 20 elements)"}, {"label": "Sodium example", "role": "11 protons, 12 neutrons, config 2,8,1"}, {"label": "Atomic (proton) number Z", "role": "number of protons; defines the element"}, {"label": "Mass (nucleon) number A", "role": "protons + neutrons"}, {"label": "Isotopes", "role": "same Z, different A (e.g. Cl-35 and Cl-37)"}], "relationships": ["Atoms are neutral: protons = electrons", "Chemistry is decided by the outer-shell electrons — the group number"], "depth_notes": {"JC": "Name the three particles and their charges.", "O-Level": "Draw configurations for the first 20 elements; define isotopes and calculate relative atomic mass from abundances.", "A-Level": "Replace shells with s/p/d orbitals and sub-shell notation (1s2 2s2 2p6 ...); explain evidence from successive ionisation energies."}, "style": "studysync-edu-v1"}'::jsonb),
('Fractional Distillation of Crude Oil','diagram','Chemistry','Organic chemistry',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/3860f0/ffffff?text=Chemistry%0ADiagram','Fractionating column with temperature gradient and the fractions drawn off at each level with their uses.','{"version": 1, "title": "Fractional Distillation of Crude Oil", "caption": "Fractionating column with temperature gradient and the fractions drawn off at each level with their uses.", "subject": "Chemistry", "topic": "Organic chemistry", "elements": [{"label": "Crude oil in furnace", "role": "heated to ~350–400°C; most of it vaporises"}, {"label": "Fractionating column", "role": "hot at the bottom, cool at the top"}, {"label": "Refinery gases (top)", "role": "bottled gas; smallest molecules, lowest boiling point"}, {"label": "Petrol (gasoline)", "role": "fuel for cars"}, {"label": "Naphtha", "role": "feedstock for chemicals and plastics"}, {"label": "Kerosene (paraffin)", "role": "jet fuel"}, {"label": "Diesel oil", "role": "fuel for lorries and trains"}, {"label": "Fuel oil", "role": "ships and power stations"}, {"label": "Bitumen (bottom)", "role": "roads and roofing; largest molecules, highest boiling point"}], "relationships": ["Separation works because hydrocarbons of different chain lengths have different boiling points", "Longer chains: higher boiling point, more viscous, less flammable, burn with smokier flame"], "depth_notes": {"O-Level": "Order the fractions, their uses, and the property trends with chain length.", "A-Level": "Link intermolecular (London) forces to boiling points; connect to cracking as the supply-demand fix for surplus heavy fractions."}, "style": "studysync-edu-v1"}'::jsonb),
('Ionic vs Covalent Bonding','diagram','Chemistry','Bonding',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/3860f0/ffffff?text=Chemistry%0ADiagram','Dot-and-cross diagrams: sodium chloride (electron transfer) beside water and methane (electron sharing), with resulting properties.','{"version": 1, "title": "Ionic vs Covalent Bonding", "caption": "Dot-and-cross diagrams: sodium chloride (electron transfer) beside water and methane (electron sharing), with resulting properties.", "subject": "Chemistry", "topic": "Bonding", "elements": [{"label": "Ionic bonding (NaCl)", "role": "Na loses 1 electron → Na+; Cl gains it → Cl−"}, {"label": "Electrostatic attraction", "role": "oppositely charged ions held in a giant lattice"}, {"label": "Covalent bonding (H2O, CH4)", "role": "atoms SHARE pairs of electrons"}, {"label": "Shared pair", "role": "one bond = one shared pair of electrons"}, {"label": "Ionic properties", "role": "high melting points; conduct when molten or dissolved"}, {"label": "Simple covalent properties", "role": "low melting points; do not conduct"}, {"label": "Dot-and-cross convention", "role": "dots for one atom''s electrons, crosses for the other''s"}], "relationships": ["Metals + non-metals → ionic (transfer); non-metals together → covalent (sharing)", "Both achieve full outer shells — the driving idea behind Group chemistry"], "depth_notes": {"O-Level": "Draw dot-and-cross diagrams for NaCl, MgO, H2O, CH4, CO2 and link structure to properties.", "A-Level": "Add electronegativity and the ionic–covalent continuum, dative bonds, and shapes by VSEPR theory."}, "style": "studysync-edu-v1"}'::jsonb),
('States of Matter and Changes of State','diagram','Chemistry','States of matter',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/3860f0/ffffff?text=Chemistry%0ADiagram','Particle diagrams of solid, liquid and gas with all six interconversions labelled and a heating curve inset.','{"version": 1, "title": "States of Matter and Changes of State", "caption": "Particle diagrams of solid, liquid and gas with all six interconversions labelled and a heating curve inset.", "subject": "Chemistry", "topic": "States of matter", "elements": [{"label": "Solid", "role": "particles in fixed regular positions, vibrating"}, {"label": "Liquid", "role": "particles close but able to slide past each other"}, {"label": "Gas", "role": "particles far apart, moving fast and randomly"}, {"label": "Melting / Freezing", "role": "solid ⇌ liquid at the melting point"}, {"label": "Boiling (evaporation) / Condensing", "role": "liquid ⇌ gas"}, {"label": "Sublimation / Deposition", "role": "solid ⇌ gas directly (e.g. iodine, CO2)"}, {"label": "Heating curve", "role": "flat sections at melting and boiling points"}], "relationships": ["During a change of state temperature stays constant — energy goes into breaking (or making) forces between particles", "Evaporation happens below the boiling point, from the surface only"], "depth_notes": {"JC": "Draw the three particle diagrams and name the six changes.", "O-Level": "Interpret heating/cooling curves and explain the flat sections using particle theory.", "A-Level": "Treat quantitatively with latent heats and ideal-gas behaviour (pV = nRT)."}, "style": "studysync-edu-v1"}'::jsonb),
