('Acid-Alkali Titration Setup','diagram','Chemistry','Acids & titration',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/3860f0/ffffff?text=Chemistry%0ADiagram','Standard titration apparatus with burette, pipette and conical flask, indicator choice and the calculation route.','{"version": 1, "title": "Acid-Alkali Titration Setup", "caption": "Standard titration apparatus with burette, pipette and conical flask, indicator choice and the calculation route.", "subject": "Chemistry", "topic": "Acids & titration", "elements": [{"label": "Burette", "role": "delivers acid with 0.05 cm3 precision; read at eye level"}, {"label": "Pipette (25.0 cm3)", "role": "measures the alkali accurately into the flask"}, {"label": "Conical flask", "role": "contains alkali + indicator; swirled constantly"}, {"label": "White tile", "role": "makes the colour change easier to see"}, {"label": "Methyl orange", "role": "red in acid, yellow in alkali"}, {"label": "Phenolphthalein", "role": "pink in alkali, colourless in acid"}, {"label": "End point", "role": "the indicator just changes colour permanently"}, {"label": "Titre", "role": "final − initial burette reading; repeat until concordant (±0.10 cm3)"}], "relationships": ["Calculation route: volume → moles (n = c×V) → mole ratio from equation → unknown concentration", "Rough titration first, then accurate runs; average only concordant titres"], "depth_notes": {"O-Level": "Name the apparatus, indicators and end-point procedure; do simple n = cV calculations.", "A-Level": "Choose the right indicator from pH curves (strong/weak combinations) and handle back-titrations."}, "style": "studysync-edu-v1"}'::jsonb),
