('Alpha, Beta and Gamma Radiation','diagram','Physics','Radioactivity',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/0e1d47/ffffff?text=Physics%0ADiagram','The three radiation types leaving a source, deflected differently in a field, with penetration barriers (paper, aluminium, lead).','{"version": 1, "title": "Alpha, Beta and Gamma Radiation", "caption": "The three radiation types leaving a source, deflected differently in a field, with penetration barriers (paper, aluminium, lead).", "subject": "Physics", "topic": "Radioactivity", "elements": [{"label": "Alpha (α)", "role": "helium nucleus (2p+2n); charge +2; stopped by paper/skin"}, {"label": "Beta (β−)", "role": "fast electron from the nucleus; charge −1; stopped by ~3 mm aluminium"}, {"label": "Gamma (γ)", "role": "EM wave; no charge; reduced by thick lead or concrete"}, {"label": "Ionising power", "role": "alpha strongest, gamma weakest"}, {"label": "Deflection", "role": "alpha and beta bend opposite ways in a field; gamma undeflected"}, {"label": "Alpha decay equation", "role": "mass number −4, atomic number −2"}, {"label": "Beta decay equation", "role": "mass number unchanged, atomic number +1"}, {"label": "Half-life", "role": "time for half the unstable nuclei to decay"}], "relationships": ["Most dangerous INSIDE the body: alpha (highly ionising); most dangerous outside: gamma (penetrates)", "Decay is random for one nucleus but statistically predictable for many — the meaning of half-life"], "depth_notes": {"O-Level": "Compare the three types (nature, charge, penetration, ionisation) and do half-life calculations.", "A-Level": "Add exponential decay N = N0e^(−λt), activity, and decay-constant/half-life relation λ = ln2/t½."}, "style": "studysync-edu-v1"}'::jsonb),
