('Features of a Quadratic Graph','diagram','Mathematics','Algebra',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/8b5cf6/ffffff?text=Mathematics%0ADiagram','A parabola y = ax² + bx + c annotated with roots, y-intercept, turning point, axis of symmetry and the effect of the sign of a.','{"version": 1, "title": "Features of a Quadratic Graph", "caption": "A parabola y = ax² + bx + c annotated with roots, y-intercept, turning point, axis of symmetry and the effect of the sign of a.", "subject": "Mathematics", "topic": "Algebra", "elements": [{"label": "Parabola", "role": "the U-shaped graph of any quadratic"}, {"label": "Roots (x-intercepts)", "role": "solutions of ax² + bx + c = 0"}, {"label": "y-intercept", "role": "the value c, at (0, c)"}, {"label": "Turning point (vertex)", "role": "minimum if a > 0, maximum if a < 0"}, {"label": "Axis of symmetry", "role": "vertical line x = −b/2a through the vertex"}, {"label": "Discriminant b² − 4ac", "role": "> 0 two roots, = 0 one repeated root, < 0 no real roots"}, {"label": "Completed square form", "role": "y = a(x − h)² + k with vertex (h, k)"}], "relationships": ["Factorised form shows the roots; completed-square form shows the vertex; standard form shows the y-intercept", "The discriminant tells you how many times the graph crosses the x-axis WITHOUT drawing it"], "depth_notes": {"O-Level": "Sketch from any form, find roots, vertex and axis of symmetry.", "A-Level": "Use the discriminant in tangency problems and inequalities."}, "style": "studysync-edu-v1"}'::jsonb),
('Venn Diagrams and Set Notation','diagram','Mathematics','Sets',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/8b5cf6/ffffff?text=Mathematics%0ADiagram','Two- and three-set Venn diagrams with every region labelled in set notation and a worked cardinality example.','{"version": 1, "title": "Venn Diagrams and Set Notation", "caption": "Two- and three-set Venn diagrams with every region labelled in set notation and a worked cardinality example.", "subject": "Mathematics", "topic": "Sets", "elements": [{"label": "Universal set ξ", "role": "the rectangle containing everything"}, {"label": "A ∪ B (union)", "role": "elements in A OR B or both"}, {"label": "A ∩ B (intersection)", "role": "elements in BOTH A and B"}, {"label": "A′ (complement)", "role": "everything NOT in A"}, {"label": "A \\ B (difference)", "role": "in A but not in B"}, {"label": "⊂ (subset)", "role": "every element of one set is in another"}, {"label": "n(A)", "role": "number of elements in A"}, {"label": "Inclusion-exclusion", "role": "n(A ∪ B) = n(A) + n(B) − n(A ∩ B)"}], "relationships": ["Shade regions systematically: work bracket-by-bracket from the inside out", "Word problems: put the intersection number in FIRST, then work outward"], "depth_notes": {"JC": "List elements of unions and intersections from a drawn diagram.", "O-Level": "Use full notation, shade compound regions, solve two- and three-set counting problems.", "A-Level": "Apply to probability: P(A ∪ B) = P(A) + P(B) − P(A ∩ B)."}, "style": "studysync-edu-v1"}'::jsonb),
('Transformations: Reflection, Rotation, Enlargement, Translation','diagram','Mathematics','Transformations',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/8b5cf6/ffffff?text=Mathematics%0ADiagram','A grid showing one object shape mapped by each of the four transformations, with the full description each exam requires.','{"version": 1, "title": "Transformations: Reflection, Rotation, Enlargement, Translation", "caption": "A grid showing one object shape mapped by each of the four transformations, with the full description each exam requires.", "subject": "Mathematics", "topic": "Transformations", "elements": [{"label": "Translation", "role": "slide by a column vector; shape and size unchanged"}, {"label": "Reflection", "role": "flip in a mirror line; state the LINE (e.g. y = x)"}, {"label": "Rotation", "role": "turn; state CENTRE, ANGLE and DIRECTION"}, {"label": "Enlargement", "role": "state CENTRE and SCALE FACTOR k"}, {"label": "Negative scale factor", "role": "image appears on the opposite side of the centre, inverted"}, {"label": "Fractional scale factor", "role": "0 < k < 1 shrinks the shape"}, {"label": "Congruent vs similar", "role": "translation/reflection/rotation keep congruence; enlargement gives similarity"}], "relationships": ["Full marks need the FULL description — naming the transformation alone scores little", "Tracing paper is allowed for rotations in most exams — use it"], "depth_notes": {"JC": "Perform each transformation on a grid.", "O-Level": "Fully describe single transformations and find centres of rotation/enlargement.", "A-Level": "Represent transformations with matrices and combine them."}, "style": "studysync-edu-v1"}'::jsonb),
('Cumulative Frequency Curve and Box Plot','diagram','Mathematics','Statistics',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/8b5cf6/ffffff?text=Mathematics%0ADiagram','A cumulative frequency ogive with median and quartiles read off, and the matching box plot drawn underneath.','{"version": 1, "title": "Cumulative Frequency Curve and Box Plot", "caption": "A cumulative frequency ogive with median and quartiles read off, and the matching box plot drawn underneath.", "subject": "Mathematics", "topic": "Statistics", "elements": [{"label": "Cumulative frequency", "role": "running total, plotted at UPPER class boundaries"}, {"label": "Ogive", "role": "the smooth S-shaped curve"}, {"label": "Median", "role": "read across from half the total frequency"}, {"label": "Lower quartile Q1", "role": "read at one-quarter of the total"}, {"label": "Upper quartile Q3", "role": "read at three-quarters"}, {"label": "Interquartile range", "role": "IQR = Q3 − Q1; spread of the middle 50%"}, {"label": "Box plot", "role": "minimum, Q1, median, Q3, maximum on one diagram"}], "relationships": ["Plot at upper class boundaries — plotting at midpoints is the classic error", "Compare two distributions with medians (average) AND IQRs (consistency)"], "depth_notes": {"O-Level": "Draw the ogive, read median/quartiles, construct and compare box plots.", "A-Level": "Link to percentiles, outlier fences (1.5 × IQR) and skewness."}, "style": "studysync-edu-v1"}'::jsonb),
('Cross-Section of a Composite Volcano','diagram','Geography','Volcanoes',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/b45309/ffffff?text=Geography%0ADiagram','Cut-away of a stratovolcano showing internal structure and eruption features.','{"version": 1, "title": "Cross-Section of a Composite Volcano", "caption": "Cut-away of a stratovolcano showing internal structure and eruption features.", "subject": "Geography", "topic": "Volcanoes", "elements": [{"label": "Magma chamber", "role": "reservoir of molten rock beneath the volcano"}, {"label": "Conduit (main vent)", "role": "central pipe magma rises through"}, {"label": "Central crater", "role": "opening at the summit"}, {"label": "Secondary (parasitic) vents", "role": "smaller outlets on the flanks"}, {"label": "Alternating layers (strata)", "role": "hardened lava and ash from previous eruptions"}, {"label": "Lava flow", "role": "molten rock moving downslope"}, {"label": "Ash cloud", "role": "fine fragments blasted into the atmosphere"}], "relationships": ["Composite volcanoes form at destructive plate margins from viscous, gas-rich magma → steep sides and explosive eruptions", "Contrast with shield volcanoes: runny basaltic lava, gentle slopes, effusive eruptions"], "depth_notes": {"JC": "Label the main parts of a volcano.", "O-Level": "Explain formation at destructive margins and compare composite vs shield volcanoes; case study of one eruption.", "A-Level": "Link magma chemistry (silica content) to eruption style, VEI, and hazard-management strategies."}, "style": "studysync-edu-v1"}'::jsonb),
('Meander and Oxbow Lake Formation','diagram','Geography','Rivers',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/b45309/ffffff?text=Geography%0ADiagram','Four-stage sequence showing a meander migrating until the neck is cut through, leaving an oxbow lake.','{"version": 1, "title": "Meander and Oxbow Lake Formation", "caption": "Four-stage sequence showing a meander migrating until the neck is cut through, leaving an oxbow lake.", "subject": "Geography", "topic": "Rivers", "elements": [{"label": "Outer bank (river cliff)", "role": "fastest flow → erosion (hydraulic action, abrasion)"}, {"label": "Inner bank (slip-off slope)", "role": "slowest flow → deposition of point bar"}, {"label": "Thalweg", "role": "line of fastest flow swinging side to side"}, {"label": "Meander neck", "role": "narrowing land between two bends"}, {"label": "Breakthrough", "role": "river cuts across the neck in flood"}, {"label": "Oxbow lake", "role": "abandoned curved lake sealed off by deposition"}], "relationships": ["Erosion on the outside + deposition on the inside makes the bend migrate and exaggerate over time", "Found in the middle/lower course where lateral erosion dominates"], "depth_notes": {"JC": "Describe a meander and name an oxbow lake.", "O-Level": "Explain the full formation sequence with erosion/deposition processes named.", "A-Level": "Add helicoidal flow, sinuosity ratios and floodplain evolution."}, "style": "studysync-edu-v1"}'::jsonb),
('Types of Plate Boundary','diagram','Geography','Plate tectonics',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/b45309/ffffff?text=Geography%0ADiagram','Three-panel diagram: constructive, destructive and conservative plate margins with arrows and resulting landforms.','{"version": 1, "title": "Types of Plate Boundary", "caption": "Three-panel diagram: constructive, destructive and conservative plate margins with arrows and resulting landforms.", "subject": "Geography", "topic": "Plate tectonics", "elements": [{"label": "Constructive (divergent)", "role": "plates move APART; new crust forms; e.g. Mid-Atlantic Ridge"}, {"label": "Destructive (convergent)", "role": "oceanic plate subducts under continental; deep-sea trench + fold mountains + volcanoes"}, {"label": "Conservative (transform)", "role": "plates slide PAST each other; earthquakes but no volcanoes; e.g. San Andreas Fault"}, {"label": "Subduction zone", "role": "denser oceanic plate sinks and melts"}, {"label": "Convection currents", "role": "in the mantle, driving plate motion"}, {"label": "Earthquake foci", "role": "shallow at constructive, deep along the Benioff zone at destructive"}], "relationships": ["Volcano + earthquake pattern around the world maps onto the plate boundaries (Pacific Ring of Fire)", "Collision margins (continental–continental) build fold mountains with no volcanoes — e.g. the Himalayas"], "depth_notes": {"O-Level": "Name the three boundary types, their movements, landforms and one example each.", "A-Level": "Evaluate slab-pull vs ridge-push vs convection as driving mechanisms; palaeomagnetic evidence."}, "style": "studysync-edu-v1"}'::jsonb),
('The Hydrological (Water) Cycle','diagram','Geography','Water cycle',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/b45309/ffffff?text=Geography%0ADiagram','Landscape diagram of the water cycle with every transfer and store labelled.','{"version": 1, "title": "The Hydrological (Water) Cycle", "caption": "Landscape diagram of the water cycle with every transfer and store labelled.", "subject": "Geography", "topic": "Water cycle", "elements": [{"label": "Evaporation", "role": "liquid water → vapour from oceans and lakes"}, {"label": "Transpiration", "role": "water vapour released from plant leaves"}, {"label": "Condensation", "role": "vapour cools into cloud droplets"}, {"label": "Precipitation", "role": "rain, snow, hail falling to the surface"}, {"label": "Surface run-off", "role": "water flowing over the ground to rivers"}, {"label": "Infiltration", "role": "water soaking into the soil"}, {"label": "Groundwater flow", "role": "slow movement through rock (aquifers)"}, {"label": "Stores", "role": "oceans, ice caps, lakes, soil, groundwater, atmosphere"}], "relationships": ["A closed system at global scale — water is transferred, never lost", "Human impacts: urbanisation increases run-off (less infiltration) → flashier river regimes"], "depth_notes": {"JC": "Name and order the main processes.", "O-Level": "Distinguish transfers from stores; apply to a drainage-basin system with inputs/outputs.", "A-Level": "Quantify with water balance (P = Q + E ± ΔS) and interpret storm hydrographs."}, "style": "studysync-edu-v1"}'::jsonb),
('The Structure of the Earth','diagram','Geography','Earth structure',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/b45309/ffffff?text=Geography%0ADiagram','Cut-away sphere showing the Earth''s layers with state, composition and approximate temperature of each.','{"version": 1, "title": "The Structure of the Earth", "caption": "Cut-away sphere showing the Earth''s layers with state, composition and approximate temperature of each.", "subject": "Geography", "topic": "Earth structure", "elements": [{"label": "Crust", "role": "thin rocky shell; continental (30–70 km) vs oceanic (5–10 km)"}, {"label": "Mantle", "role": "thickest layer; hot semi-molten rock (asthenosphere flows slowly)"}, {"label": "Outer core", "role": "liquid iron and nickel; source of the magnetic field"}, {"label": "Inner core", "role": "solid iron-nickel ball ~5,500°C — solid because of immense pressure"}, {"label": "Lithosphere", "role": "crust + rigid upper mantle; broken into tectonic plates"}, {"label": "Convection currents", "role": "heat-driven circulation in the mantle"}], "relationships": ["Continental crust is thicker but LESS dense than oceanic — why oceanic subducts", "Evidence comes from seismic waves: S-waves cannot pass through the liquid outer core"], "depth_notes": {"JC": "Name the four main layers in order.", "O-Level": "Describe each layer''s state and composition; link convection to plate movement.", "A-Level": "Use seismic-wave shadow zones as evidence for internal structure."}, "style": "studysync-edu-v1"}'::jsonb),
('Supply and Demand: Market Equilibrium and Shifts','diagram','Economics','Markets',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/1a7f4b/ffffff?text=Economics%0ADiagram','Supply and demand curves crossing at equilibrium, with a rightward demand shift showing the new higher price and quantity.','{"version": 1, "title": "Supply and Demand: Market Equilibrium and Shifts", "caption": "Supply and demand curves crossing at equilibrium, with a rightward demand shift showing the new higher price and quantity.", "subject": "Economics", "topic": "Markets", "elements": [{"label": "Demand curve (D1)", "role": "downward sloping: price up → quantity demanded down"}, {"label": "Supply curve (S1)", "role": "upward sloping: price up → quantity supplied up"}, {"label": "Equilibrium (E1)", "role": "where supply = demand; market clears at P1, Q1"}, {"label": "Demand shift (D1→D2)", "role": "increase in demand moves the curve RIGHT"}, {"label": "New equilibrium (E2)", "role": "both price (P2) and quantity (Q2) rise"}, {"label": "Excess demand", "role": "below equilibrium price: shortage pushes price up"}, {"label": "Excess supply", "role": "above equilibrium price: surplus pushes price down"}], "relationships": ["Movements ALONG a curve are caused only by price; SHIFTS are caused by everything else (income, tastes, substitutes, costs...)", "Shift one curve at a time and read the new intersection — the universal exam method"], "depth_notes": {"O-Level": "Draw and label the diagram, distinguish shifts from movements, predict price/quantity changes.", "A-Level": "Add elasticities (PED, PES, YED, XED), consumer/producer surplus and government intervention (taxes, ceilings, floors)."}, "style": "studysync-edu-v1"}'::jsonb),
('The Production Possibility Curve (PPC)','diagram','Economics','Production possibilities',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/1a7f4b/ffffff?text=Economics%0ADiagram','A concave PPC for two goods with points illustrating efficiency, unemployment, unattainability, opportunity cost and growth.','{"version": 1, "title": "The Production Possibility Curve (PPC)", "caption": "A concave PPC for two goods with points illustrating efficiency, unemployment, unattainability, opportunity cost and growth.", "subject": "Economics", "topic": "Production possibilities", "elements": [{"label": "PPC / PPF", "role": "maximum combinations of two goods an economy can produce"}, {"label": "Point ON the curve", "role": "productive efficiency — all resources fully used"}, {"label": "Point INSIDE", "role": "unemployment / inefficiency"}, {"label": "Point OUTSIDE", "role": "unattainable with current resources"}, {"label": "Movement along the curve", "role": "opportunity cost: giving up some of one good for more of the other"}, {"label": "Concave shape", "role": "increasing opportunity cost (resources are not equally suited to both goods)"}, {"label": "Outward shift", "role": "economic growth: more resources or better technology"}], "relationships": ["The PPC turns scarcity, choice and opportunity cost — the three core concepts — into one picture", "Capital vs consumer goods choice today changes how far the curve shifts tomorrow"], "depth_notes": {"O-Level": "Interpret every point/region and define opportunity cost from the diagram.", "A-Level": "Analyse increasing marginal opportunity cost, actual vs potential growth and trade-enabled consumption outside the PPC."}, "style": "studysync-edu-v1"}'::jsonb),
('The Circular Flow of Income','diagram','Economics','National income',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/1a7f4b/ffffff?text=Economics%0ADiagram','Households and firms connected by real flows and money flows, with injections and withdrawals labelled.','{"version": 1, "title": "The Circular Flow of Income", "caption": "Households and firms connected by real flows and money flows, with injections and withdrawals labelled.", "subject": "Economics", "topic": "National income", "elements": [{"label": "Households", "role": "supply factors of production; spend on goods and services"}, {"label": "Firms", "role": "produce output; pay factor incomes (wages, rent, interest, profit)"}, {"label": "Real flow", "role": "factors of production → firms; goods and services → households"}, {"label": "Money flow", "role": "factor incomes → households; consumer spending → firms"}, {"label": "Injections (J)", "role": "investment + government spending + exports"}, {"label": "Withdrawals/leakages (W)", "role": "savings + taxes + imports"}, {"label": "Equilibrium", "role": "income stable when J = W"}], "relationships": ["If injections exceed withdrawals, national income grows (and vice versa)", "Foundation for GDP measurement: income = output = expenditure"], "depth_notes": {"O-Level": "Draw the two-sector flow and add injections and withdrawals.", "A-Level": "Link to the multiplier effect and the three methods of measuring GDP."}, "style": "studysync-edu-v1"}'::jsonb),
('The Business (Trade) Cycle','diagram','Economics','Macroeconomy',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/1a7f4b/ffffff?text=Economics%0ADiagram','GDP over time showing boom, downturn/recession, trough and recovery around a long-run growth trend line.','{"version": 1, "title": "The Business (Trade) Cycle", "caption": "GDP over time showing boom, downturn/recession, trough and recovery around a long-run growth trend line.", "subject": "Economics", "topic": "Macroeconomy", "elements": [{"label": "Boom (peak)", "role": "high output and employment; rising inflation pressure"}, {"label": "Downturn / recession", "role": "falling output; two consecutive quarters of negative GDP growth"}, {"label": "Trough (slump)", "role": "lowest point; high unemployment, low confidence"}, {"label": "Recovery", "role": "output rising back toward trend"}, {"label": "Trend growth line", "role": "long-run average path of real GDP"}, {"label": "Output gap", "role": "distance between actual GDP and trend"}], "relationships": ["Each phase pairs with typical policy responses: recessions invite expansionary fiscal/monetary policy, booms the reverse", "Indicators to watch: unemployment (lags), inflation (rises in booms), investment and confidence (lead)"], "depth_notes": {"O-Level": "Label the phases and describe what happens to jobs and prices in each.", "A-Level": "Analyse demand-side vs supply-side causes, output gaps and stabilisation-policy debates."}, "style": "studysync-edu-v1"}'::jsonb),
('The Break-Even Chart','diagram','Business Studies','Finance',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/be185d/ffffff?text=Business+Studies%0ADiagram','Revenue and cost lines against output with the break-even point, margin of safety, and profit/loss regions shaded.','{"version": 1, "title": "The Break-Even Chart", "caption": "Revenue and cost lines against output with the break-even point, margin of safety, and profit/loss regions shaded.", "subject": "Business Studies", "topic": "Finance", "elements": [{"label": "Fixed costs line", "role": "horizontal — do not change with output (rent, salaries)"}, {"label": "Variable costs", "role": "rise with each unit produced (materials)"}, {"label": "Total costs line", "role": "fixed + variable; starts at the fixed-cost level"}, {"label": "Total revenue line", "role": "price × quantity; starts at the origin"}, {"label": "Break-even point", "role": "where total revenue = total costs; no profit, no loss"}, {"label": "Profit region", "role": "right of break-even (revenue above costs)"}, {"label": "Loss region", "role": "left of break-even"}, {"label": "Margin of safety", "role": "actual output − break-even output"}], "relationships": ["Formula: break-even output = fixed costs ÷ (selling price − variable cost per unit), i.e. fixed costs ÷ contribution", "Uses: pricing decisions, loan applications, what-if analysis; limits: assumes everything made is sold and linear costs"], "depth_notes": {"O-Level": "Draw/label the chart, calculate break-even output and margin of safety.", "A-Level": "Evaluate contribution analysis, stepped fixed costs and the model''s assumptions."}, "style": "studysync-edu-v1"}'::jsonb),
('The Product Life Cycle','diagram','Business Studies','Marketing',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/be185d/ffffff?text=Business+Studies%0ADiagram','Sales (and profit) curves over time through introduction, growth, maturity, decline — with extension strategies arrowed at maturity.','{"version": 1, "title": "The Product Life Cycle", "caption": "Sales (and profit) curves over time through introduction, growth, maturity, decline — with extension strategies arrowed at maturity.", "subject": "Business Studies", "topic": "Marketing", "elements": [{"label": "Introduction", "role": "launch; low sales, heavy promotion, often loss-making"}, {"label": "Growth", "role": "sales rise fast; profits appear; competitors enter"}, {"label": "Maturity", "role": "sales peak and flatten; competition intense; prices pressured"}, {"label": "Decline", "role": "sales fall as tastes/technology move on"}, {"label": "Extension strategies", "role": "new markets, new uses, redesign, repackaging, promotion to prolong maturity"}, {"label": "Profit curve", "role": "lags the sales curve; peaks during growth/early maturity"}], "relationships": ["Marketing mix changes at every stage — e.g. price skimming at introduction, defensive promotion at maturity", "Link to cash flow: introduction consumes cash, maturity generates it (Boston Matrix ''cash cow'')"], "depth_notes": {"O-Level": "Label the stages and suggest suitable extension strategies for a named product.", "A-Level": "Integrate with portfolio analysis (Boston Matrix) and capacity/cash-flow planning."}, "style": "studysync-edu-v1"}'::jsonb),
('The Fetch-Decode-Execute Cycle','diagram','Computer Science','CPU architecture',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/475569/ffffff?text=Computer+Science%0ADiagram','CPU internals (CU, ALU, registers) connected to RAM by buses, with the three-step instruction cycle numbered.','{"version": 1, "title": "The Fetch-Decode-Execute Cycle", "caption": "CPU internals (CU, ALU, registers) connected to RAM by buses, with the three-step instruction cycle numbered.", "subject": "Computer Science", "topic": "CPU architecture", "elements": [{"label": "Control Unit (CU)", "role": "directs operations; decodes instructions"}, {"label": "Arithmetic Logic Unit (ALU)", "role": "performs calculations and logical comparisons"}, {"label": "Registers", "role": "tiny, fastest storage inside the CPU (PC, MAR, MDR, ACC, CIR)"}, {"label": "Main memory (RAM)", "role": "stores the instructions and data of running programs"}, {"label": "Address bus", "role": "carries memory ADDRESSES (one direction: CPU → RAM)"}, {"label": "Data bus", "role": "carries data and instructions (both directions)"}, {"label": "1. FETCH", "role": "next instruction copied from RAM (address in PC) into the CPU"}, {"label": "2. DECODE", "role": "CU works out what the instruction means"}, {"label": "3. EXECUTE", "role": "the operation is carried out (ALU, memory access, or jump)"}], "relationships": ["The cycle repeats millions of times per second — clock speed = cycles per second (Hz)", "Program Counter increments each fetch, so instructions run in sequence unless a jump changes it"], "depth_notes": {"O-Level": "Name the CPU components, buses and the three steps of the cycle.", "A-Level": "Trace register transfers (PC→MAR, [MAR]→MDR, MDR→CIR...) and analyse pipelining and performance factors."}, "style": "studysync-edu-v1"}'::jsonb),
('Logic Gates and Truth Tables','diagram','Computer Science','Logic',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/475569/ffffff?text=Computer+Science%0ADiagram','The six standard logic gates with symbols and truth tables, plus a small two-gate combined circuit example.','{"version": 1, "title": "Logic Gates and Truth Tables", "caption": "The six standard logic gates with symbols and truth tables, plus a small two-gate combined circuit example.", "subject": "Computer Science", "topic": "Logic", "elements": [{"label": "NOT gate", "role": "inverts: output 1 when input 0"}, {"label": "AND gate", "role": "output 1 only when BOTH inputs are 1"}, {"label": "OR gate", "role": "output 1 when AT LEAST one input is 1"}, {"label": "NAND gate", "role": "AND followed by NOT; output 0 only when both inputs 1"}, {"label": "NOR gate", "role": "OR followed by NOT; output 1 only when both inputs 0"}, {"label": "XOR gate", "role": "output 1 when inputs are DIFFERENT"}, {"label": "Truth table", "role": "every input combination with the resulting output"}, {"label": "Combined circuit", "role": "gates chained; build the table column by column"}], "relationships": ["n inputs → 2^n rows in the truth table", "NAND is ''universal'' — any circuit can be built from NAND gates alone"], "depth_notes": {"O-Level": "Draw symbols, complete truth tables, and derive tables for 2–3 gate circuits.", "A-Level": "Write and simplify Boolean expressions (De Morgan''s laws, Karnaugh maps)."}, "style": "studysync-edu-v1"}'::jsonb),
('Network Topologies: Bus, Star and Mesh','diagram','Computer Science','Networks',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/475569/ffffff?text=Computer+Science%0ADiagram','Three small network diagrams — bus, star and mesh — with advantages and failure behaviour of each.','{"version": 1, "title": "Network Topologies: Bus, Star and Mesh", "caption": "Three small network diagrams — bus, star and mesh — with advantages and failure behaviour of each.", "subject": "Computer Science", "topic": "Networks", "elements": [{"label": "Bus topology", "role": "all devices share one backbone cable with terminators"}, {"label": "Bus weakness", "role": "backbone break kills the whole network; collisions as traffic grows"}, {"label": "Star topology", "role": "every device has its own cable to a central switch"}, {"label": "Star strengths", "role": "one cable failing affects only that device; easy to add devices"}, {"label": "Star weakness", "role": "the switch is a single point of failure"}, {"label": "Mesh topology", "role": "devices interconnected with multiple redundant paths"}, {"label": "Mesh strengths", "role": "very fault-tolerant; no single point of failure (full mesh)"}, {"label": "Mesh weakness", "role": "expensive: many cables/links; complex to manage"}], "relationships": ["Choice = trade-off between cost, performance and resilience", "Modern LANs are almost always star (switched Ethernet/Wi-Fi); mesh dominates where uptime is critical and in wireless IoT"], "depth_notes": {"O-Level": "Draw each topology and compare advantages, disadvantages and failure modes.", "A-Level": "Add packet switching, routing redundancy and performance analysis."}, "style": "studysync-edu-v1"}'::jsonb),
('The Accounting Equation and the Balance Sheet','diagram','Accounting','Fundamentals',NULL,ARRAY['Form 3','Form 4','O-Level','IGCSE','Grade 10','Grade 11','Form 5','Form 6','A-Level','Grade 12'],'https://placehold.co/320x400/9333ea/ffffff?text=Accounting%0ADiagram','The accounting equation ASSETS = LIABILITIES + CAPITAL expanded into a simple classified balance sheet layout.','{"version": 1, "title": "The Accounting Equation and the Balance Sheet", "caption": "The accounting equation ASSETS = LIABILITIES + CAPITAL expanded into a simple classified balance sheet layout.", "subject": "Accounting", "topic": "Fundamentals", "elements": [{"label": "Assets", "role": "resources the business OWNS (non-current + current)"}, {"label": "Non-current assets", "role": "held long-term: premises, machinery, vehicles"}, {"label": "Current assets", "role": "cash or near-cash: inventory, receivables, bank"}, {"label": "Liabilities", "role": "amounts the business OWES (non-current + current)"}, {"label": "Current liabilities", "role": "due within a year: payables, overdraft"}, {"label": "Capital (owner''s equity)", "role": "owner''s investment + profits − drawings"}, {"label": "The equation", "role": "Assets = Liabilities + Capital — always balances"}, {"label": "Dual aspect", "role": "every transaction affects two items, keeping the equation true"}], "relationships": ["Every transaction keeps the equation balanced — buy a machine with cash and one asset simply replaces another", "The balance sheet is the equation written out at one moment in time"], "depth_notes": {"O-Level": "State the equation, classify items, and show the effect of transactions on it.", "A-Level": "Extend to company formats: share capital, reserves, and IAS-style statement of financial position."}, "style": "studysync-edu-v1"}'::jsonb)
